const std = @import("std");

pub fn main() !void {
    const arr = [_]i32{ 3, 7, 11, 18, 25, 42, 56, 71, 88, 99 };
    const target: i32 = 42;
    var left: usize = 0;
    var right: usize = arr.len - 1;
    var found: ?usize = null;

    while (left <= right) {
        const mid = left + (right - left) / 2;
        if (arr[mid] == target) {
            found = mid;
            break;
        } else if (arr[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    if (found) |idx| {
        std.debug.print("Found {} at index {}\n", .{target, idx});
    } else {
        std.debug.print("{} not found\n", .{target});
    }
}
